/** 资源文件基础地址（MinIO 等文件服务）。由构建期 .env 的 VITE_FILE_BASE_URL 注入；
 * 未配置时回退同源，适配 /zhi2-dev 等由网关/反代同源托管的场景。 */
function fileBaseUrl(): string {
  const env = import.meta.env as Record<string, string | undefined>
  return (env.VITE_FILE_BASE_URL ?? '').replace(/\/$/, '')
}

/**
 * 将接口返回的相对资源路径解析为可访问的绝对 URL。
 * - 已是绝对地址（http(s):// 或 //）原样返回；
 * - 否则按 VITE_FILE_BASE_URL 拼接；未配置基础地址时回退同源（window.location.origin）。
 */
export function resolveResourceUrl(rel?: string | null): string {
  const raw = (rel ?? '').trim()
  if (!raw) return ''
  if (/^(https?:)?\/\//i.test(raw)) return raw
  const base = fileBaseUrl()
  const sep = raw.startsWith('/') ? '' : '/'
  return base ? `${base}${sep}${raw}` : `${window.location.origin}${sep}${raw}`
}

